def build(pair):
    d = PairData(pair, with_labels=True)
    stats, votes = {}, {}
    tl = {}  # (view, local) -> [first, last, n_present]
    for t in range(1, d.frames + 1):
        f = d.frame(t)
        emb, view, cls, pid = f['emb'], f['view'], f['cls'], f['pid']
        bbox = np.array([r['bbox'] for r in f['rows']], dtype=np.float64)
        local = np.array([r['local_track_id_index'] for r in f['rows']], dtype=np.int64)
        present = np.array([r['feature_present'] for r in f['rows']], dtype=bool)
        for v in (0, 1):
            for li in local[(view == v) & present]:
                e = tl.setdefault((v, int(li)), [t, t, 0])
                e[1] = t
                e[2] += 1
        for v in (0, 1):
            m = present & (view == v) & (pid >= 0)
            for li, pi in zip(local[m], pid[m]):
                votes.setdefault((v, int(li)), {})
                votes[(v, int(li))][int(pi)] = votes[(v, int(li))].get(int(pi), 0) + 1

